    rb=next((r for r,row in enumerate(grid) if all(x==row[0] and x!=bg for x in row)),None)
    cb=next((c for c in range(w) if all(grid[r][c]==grid[0][c] and grid[0][c]!=bg for r in range(h))),None)
    if rb is not None:
        # Extend a parallel color-8 stripe into the gap between the object and separator.
        obj=[r for r in range(h) if r!=rb and any(x!=bg for x in grid[r])]
        if obj:
            target=max(obj)+1 if max(obj)<rb else min(obj)-1
            if 0<=target<h:out[target]=[8]*w
    elif cb is not None:
        obj=[c for c in range(w) if c!=cb and any(grid[r][c]!=bg for r in range(h))]
        if obj:
            target=min(obj)-1 if max(obj)<cb else max(obj)+1
            if 0<=target<w:
                for r in range(h):out[r][target]=8
    return out
